JOIN dbo.LookupCode c ON c.Entity = 'Country' AND c.InternalCode = CASE WHEN v.State = 'PR' THEN 'PR' ELSE 'US' END
WHERE NOT EXISTS (SELECT 1 FROM dbo.PostalLocality p WHERE p.PostalCode = v.Zip);
